/* 네트워크 우선. 이전 Jekyll 캐시만 정리하고 오프라인 캐시는 만들지 않는다. */
self.addEventListener('install',()=>self.skipWaiting());
self.addEventListener('activate',event=>event.waitUntil((async()=>{
 for(const key of await caches.keys())if(/^(chirpy|fredko-blog)/i.test(key))await caches.delete(key);
 await self.clients.claim();
})()));
